SELECT     il.ITEM AS \"Item ID\",     im.ITEM_DESC AS \"Item Description\",     im.DEPT AS \"Department Number\",     d.DEPT_NAME AS \"Department Name\",     im.CLASS AS \"Class Number\",     im.SUBCLASS AS \"Subclass Number\",     il.LOC AS \"Location ID\",     il.LOC_TYPE AS \"Location Type\",     CASE il.LOC_TYPE WHEN 'S' THEN st.STORE_NAME WHEN 'W' THEN wh.WH_NAME END AS \"Location Name\",     il.STATUS AS \"Item Location Status\",     il.RANGED_IND AS \"Ranged Indicator\",     ils.STOCK_ON_HAND AS \"On Hand Quantity\",     ils.TSF_RESERVED_QTY AS \"Reserved Quantity\",     ils.NON_SELLABLE_QTY AS \"Non-Sellable Quantity\",     NVL(ils.STOCK_ON_HAND, 0) + NVL(ils.TSF_RESERVED_QTY, 0) + NVL(ils.NON_SELLABLE_QTY, 0) AS \"Unexpected Inventory Total\",     ils.RTV_QTY AS \"Return to Vendor Pending Quantity\",     ils.CUSTOMER_RESV AS \"Customer Reserved Quantity\",     ils.AV_COST AS \"Weighted Average Cost\",     il.SELLING_UNIT_RETAIL AS \"Unit Retail\",     ROUND(NVL(ils.STOCK_ON_HAND, 0) * NVL(ils.AV_COST, 0), 2) AS \"Stock on Hand Cost Value\",     ROUND(NVL(ils.STOCK_ON_HAND, 0) * NVL(il.SELLING_UNIT_RETAIL, 0), 2) AS \"Stock on Hand Retail Value\",     CASE WHEN NVL(ils.STOCK_ON_HAND, 0) &lt; 0 THEN 'YES' ELSE 'NO' END AS \"Negative Stock on Hand Indicator\",     CASE         WHEN NVL(ils.STOCK_ON_HAND, 0) &lt; 0 THEN 'NEGATIVE SOH'         WHEN il.STATUS IN ('C','I','D') AND NVL(ils.STOCK_ON_HAND, 0) != 0 THEN 'NON-ACTIVE WITH INVENTORY'         WHEN il.STATUS = 'A' AND NVL(il.RANGED_IND, 'N') = 'N' AND NVL(ils.STOCK_ON_HAND, 0) != 0 THEN 'ACTIVE NOT RANGED WITH INVENTORY'         ELSE 'OTHER'     END AS \"Unexpected Inventory Type\",     CASE         WHEN NVL(ils.STOCK_ON_HAND, 0) &lt; 0 THEN '1-CRITICAL'         WHEN il.STATUS = 'D' AND NVL(ils.STOCK_ON_HAND, 0) &gt; 0 THEN '2-HIGH'         WHEN il.STATUS = 'I' AND NVL(ils.STOCK_ON_HAND, 0) &gt; 0 THEN '3-HIGH'         WHEN il.STATUS = 'C' AND NVL(ils.STOCK_ON_HAND, 0) &gt; 0 THEN '4-MEDIUM'         WHEN il.STATUS = 'A' AND NVL(il.RANGED_IND, 'N') = 'N' AND NVL(ils.STOCK_ON_HAND, 0) &gt; 0 THEN '5-MEDIUM'         ELSE '6-LOW'     END AS \"Issue Priority\",     il.STATUS_UPDATE_DATE AS \"Status Last Changed Date\"      FROM rds_wv_item_loc il INNER JOIN rds_wv_item_master im ON il.ITEM = im.ITEM INNER JOIN rds_wv_deps d ON im.DEPT = d.DEPT INNER JOIN rds_wv_item_loc_soh ils ON il.ITEM = ils.ITEM AND il.LOC = ils.LOC AND il.LOC_TYPE = ils.LOC_TYPE LEFT JOIN rds_wv_store st ON il.LOC = st.STORE AND il.LOC_TYPE = 'S' LEFT JOIN rds_wv_wh wh ON il.LOC = wh.WH AND il.LOC_TYPE = 'W' WHERE (     NVL(ils.STOCK_ON_HAND, 0) &lt; 0     OR (il.STATUS IN ('C','I','D') AND NVL(ils.STOCK_ON_HAND, 0) != 0)     OR (il.STATUS = 'A' AND NVL(il.RANGED_IND, 'N') = 'N' AND NVL(ils.STOCK_ON_HAND, 0) != 0) ) AND im.STATUS = 'A'</ds:dbquery><ds:target_type>Oracle 12c</ds:target_type><ds:object_name/></ds:dataptr><ds:columns><ds:column><ds:name>Item ID</ds:name><ds:datatype>varchar(25)</ds:datatype><ds:nullable>false</ds:nullable></ds:column><ds:column><ds:name>Item Description</ds:name><ds:datatype>varchar(250)</ds:datatype><ds:nullable>false</ds:nullable></ds:column><ds:column><ds:name>Department Number</ds:name><ds:datatype>number</ds:datatype><ds:nullable>false</ds:nullable></ds:column><ds:column><ds:name>Department Name</ds:name><ds:datatype>varchar(120)</ds:datatype><ds:nullable>false</ds:nullable></ds:column><ds:column><ds:name>Class Number</ds:name><ds:datatype>number</ds:datatype><ds:nullable>false</ds:nullable></ds:column><ds:column><ds:name>Subclass Number</ds:name><ds:datatype>number</ds:datatype><ds:nullable>false</ds:nullable></ds:column><ds:column><ds:name>Location ID</ds:name><ds:datatype>number</ds:datatype><ds:nullable>false</ds:nullable></ds:column><ds:column><ds:name>Location Type</ds:name><ds:datatype>varchar(1)</ds:datatype><ds:nullable>false</ds:nullable></ds:column><ds:column><ds:name>Location Name</ds:name><ds:datatype>varchar(150)</ds:datatype></ds:column><ds:column><