-- ── Query 2 ────────────────────────────────────────────────────────────
SELECT\\n    il.ITEM AS \\\"Item ID\\\",\\n    im.ITEM_DESC AS \\\"Item Description\\\",\\n    im.DEPT AS \\\"Department Number\\\",\\n    d.DEPT_NAME AS \\\"Department Name\\\",\\n    im.CLASS AS \\\"Class Number\\\",\\n    im.SUBCLASS AS \\\"Subclass Number\\\",\\n    il.LOC AS \\\"Location ID\\\",\\n    il.LOC_TYPE AS \\\"Location Type\\\",\\n    CASE il.LOC_TYPE WHEN 'S' THEN st.STORE_NAME WHEN 'W' THEN wh.WH_NAME END AS \\\"Location Name\\\",\\n    il.STATUS AS \\\"Item Location Status\\\",\\n    il.RANGED_IND AS \\\"Ranged Indicator\\\",\\n    ils.STOCK_ON_HAND AS \\\"On Hand Quantity\\\",\\n    ils.TSF_RESERVED_QTY AS \\\"Reserved Quantity\\\",\\n    ils.NON_SELLABLE_QTY AS \\\"Non-Sellable Quantity\\\",\\n    NVL(ils.STOCK_ON_HAND, 0) + NVL(ils.TSF_RESERVED_QTY, 0) + NVL(ils.NON_SELLABLE_QTY, 0) AS \\\"Unexpected Inventory Total\\\",\\n    ils.RTV_QTY AS \\\"Return to Vendor Pending Quantity\\\",\\n    ils.CUSTOMER_RESV AS \\\"Customer Reserved Quantity\\\",\\n    ils.AV_COST AS \\\"Weighted Average Cost\\\",\\n    il.SELLING_UNIT_RETAIL AS \\\"Unit Retail\\\",\\n    ROUND(NVL(ils.STOCK_ON_HAND, 0) * NVL(ils.AV_COST, 0), 2) AS \\\"Stock on Hand Cost Value\\\",\\n    ROUND(NVL(ils.STOCK_ON_HAND, 0) * NVL(il.SELLING_UNIT_RETAIL, 0), 2) AS \\\"Stock on Hand Retail Value\\\",\\n    CASE WHEN NVL(ils.STOCK_ON_HAND, 0) &lt; 0 THEN 'YES' ELSE 'NO' END AS \\\"Negative Stock on Hand Indicator\\\",\\n    CASE\\n        WHEN NVL(ils.STOCK_ON_HAND, 0) &lt; 0 THEN 'NEGATIVE SOH'\\n        WHEN il.STATUS IN ('C','I','D') AND NVL(ils.STOCK_ON_HAND, 0) != 0 THEN 'NON-ACTIVE WITH INVENTORY'\\n        WHEN il.STATUS = 'A' AND NVL(il.RANGED_IND, 'N') = 'N' AND NVL(ils.STOCK_ON_HAND, 0) != 0 THEN 'ACTIVE NOT RANGED WITH INVENTORY'\\n        ELSE 'OTHER'\\n    END AS \\\"Unexpected Inventory Type\\\",\\n    CASE\\n        WHEN NVL(ils.STOCK_ON_HAND, 0) &lt; 0 THEN '1-CRITICAL'\\n        WHEN il.STATUS = 'D' AND NVL(ils.STOCK_ON_HAND, 0) &gt; 0 THEN '2-HIGH'\\n        WHEN il.STATUS = 'I' AND NVL(ils.STOCK_ON_HAND, 0) &gt; 0 THEN '3-HIGH'\\n        WHEN il.STATUS = 'C' AND NVL(ils.STOCK_ON_HAND, 0) &gt; 0 THEN '4-MEDIUM'\\n        WHEN il.STATUS = 'A' AND NVL(il.RANGED_IND, 'N') = 'N' AND NVL(ils.STOCK_ON_HAND, 0) &gt; 0 THEN '5-MEDIUM'\\n        ELSE '6-LOW'\\n    END AS \\\"Issue Priority\\\",\\n    il.STATUS_UPDATE_DATE AS \\\"Status Last Changed Date\\\" \\n    FROM rds_wv_item_loc il\\nINNER JOIN rds_wv_item_master im ON il.ITEM = im.ITEM\\nINNER JOIN rds_wv_deps d ON im.DEPT = d.DEPT\\nINNER JOIN rds_wv_item_loc_soh ils ON il.ITEM = ils.ITEM AND il.LOC = ils.LOC AND il.LOC_TYPE = ils.LOC_TYPE\\nLEFT JOIN rds_wv_store st ON il.LOC = st.STORE AND il.LOC_TYPE = 'S'\\nLEFT JOIN rds_wv_wh wh ON il.LOC = wh.WH AND il.LOC_TYPE = 'W'\\nWHERE (\\n    NVL(ils.STOCK_ON_HAND, 0) &lt; 0\\n    OR (il.STATUS IN ('C','I','D') AND NVL(ils.STOCK_ON_HAND, 0) != 0)\\n    OR (il.STATUS = 'A' AND NVL(il.RANGED_IND, 'N') = 'N' AND NVL(ils.STOCK_ON_HAND, 0) != 0)\\n)\\nAND im.STATUS = 'A'\"},\"editorCurrentState\":false,\"joins\":{\"tables\":[]}}</ds:uiOptions><ds:version>v5</ds:version></ds:datasetImportOptions>","business-model":"\"\"","active":true,"custom-attrs":"{\"src_parquet_verified\":\"true\"}","description":"External dataset","display-name":"Manual Query","locale":"sys","is-user-striped":false,"file-length":0,"type":"sql","properties-last-modified":"2026-07-31T11:10:52.361+0000","connection-namespace":"disadmin_disadmin_APPID","private-connection":false,"credential-exists":true,"connection-name":"Remote RDS MFCS Connection","provider-type":"db","provider-name":"oracle","sso-enabled":false,"datamodelname":"'ReCommon'.'RPT_412_Items on Replenishment Never Ordered'","parent-namespace":"ReCommon","parent-name":"RPT_412_Items on Replenishment Never Ordered","data-access-mode":"auto","is-data-cacheable":true,"checkpoint-metadata-stale":false,"owner-guid":"ReCommon","is-temporary":false},"datasetType":"EMBEDDED","datamodelTwoPartName":"'ReCommon'.'RPT_412_Items on Replenishment Never Ordered'"}
